using ContosoUniversity.Services;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain static queue to isolate tests
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain queue after each test
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_Create_EnqueuesNotificationWithCorrectMessage()
    {
        _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("John Doe", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_Update_GeneratesUpdateMessage()
    {
        _sut.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE, "teacher");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("UPDATE", notification.Operation);
        Assert.Contains("updated", notification.Message);
        Assert.Contains("Chemistry", notification.Message);
    }

    [Fact]
    public void SendNotification_Delete_GeneratesDeleteMessage()
    {
        _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Contains("deleted", notification.Message);
        Assert.Contains("Engineering", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
    {
        _sut.SendNotification("Student", "99", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("99", notification.Message);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToApproximateNow()
    {
        var before = DateTime.Now.AddSeconds(-1);
        _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
        var after = DateTime.Now.AddSeconds(1);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var result = _sut.ReceiveNotification();

        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_MultipleEnqueued_ReturnsFifoOrder()
    {
        _sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);
        _sut.SendNotification("C", "3", "Third", EntityOperation.DELETE);

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();
        var third = _sut.ReceiveNotification();

        Assert.Equal("A", first!.EntityType);
        Assert.Equal("B", second!.EntityType);
        Assert.Equal("C", third!.EntityType);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op for in-memory implementation, just verify it doesn't throw
        var exception = Record.Exception(() => _sut.MarkAsRead(1));
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_WithDisplayName_IncludesQuotedNameInMessage()
    {
        _sut.SendNotification("Course", "101", "Calculus", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("'Calculus'", notification.Message);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }
}

