using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;

namespace ContosoUniversity.Tests;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new StudentsController(_context);
        // Set up TempData (needed by controller)
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(), new SessionStateTempDataProvider()); // will fallback; use mock below
        SetupTempData();
    }

    private void SetupTempData()
    {
        var httpContext = new DefaultHttpContext();
        var tempData = new TempDataDictionary(httpContext, 
            Moq.Mock.Of<ITempDataProvider>());
        _controller.TempData = tempData;
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Student CreateTestStudent(string firstName = "John", string lastName = "Doe", DateTime? enrollmentDate = null)
    {
        var student = new Student
        {
            FirstMidName = firstName,
            LastName = lastName,
            EnrollmentDate = enrollmentDate ?? new DateTime(2023, 9, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();
        return student;
    }

    // ===== Index Tests =====

    [Fact]
    public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
    {
        CreateTestStudent("Alice", "Zulu");
        CreateTestStudent("Bob", "Alpha");

        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(2, model.Count);
        Assert.Equal("Alpha", model[0].LastName);
        Assert.Equal("Zulu", model[1].LastName);
    }

    [Fact]
    public void Index_NameDescSort_ReturnsStudentsInDescendingOrder()
    {
        CreateTestStudent("Alice", "Alpha");
        CreateTestStudent("Bob", "Zulu");

        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Zulu", model[0].LastName);
        Assert.Equal("Alpha", model[1].LastName);
    }

    [Fact]
    public void Index_DateSort_ReturnsStudentsOrderedByEnrollmentDate()
    {
        CreateTestStudent("Bob", "B", new DateTime(2024, 1, 1));
        CreateTestStudent("Alice", "A", new DateTime(2020, 1, 1));

        var result = _controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("A", model[0].LastName);
        Assert.Equal("B", model[1].LastName);
    }

    [Fact]
    public void Index_DateDescSort_ReturnsStudentsOrderedByEnrollmentDateDescending()
    {
        CreateTestStudent("Alice", "A", new DateTime(2020, 1, 1));
        CreateTestStudent("Bob", "B", new DateTime(2024, 1, 1));

        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("B", model[0].LastName);
        Assert.Equal("A", model[1].LastName);
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByLastName()
    {
        CreateTestStudent("Alice", "Johnson");
        CreateTestStudent("Bob", "Smith");

        var result = _controller.Index(null, null, "Smith", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Smith", model[0].LastName);
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByFirstName()
    {
        CreateTestStudent("Alice", "Johnson");
        CreateTestStudent("Bob", "Smith");

        var result = _controller.Index(null, null, "Alice", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alice", model[0].FirstMidName);
    }

    [Fact]
    public void Index_SearchStringNotNull_ResetsPageToOne()
    {
        var result = _controller.Index(null, null, "test", 5) as ViewResult;
        Assert.NotNull(result);
        // When searchString is not null, page is reset to 1
    }

    [Fact]
    public void Index_SearchStringNull_UsesCurrentFilter()
    {
        CreateTestStudent("Alice", "Johnson");
        CreateTestStudent("Bob", "Smith");

        var result = _controller.Index(null, "Smith", null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Smith", model[0].LastName);
    }

    [Fact]
    public void Index_SetsViewBagSortParameters()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
        Assert.Equal("Date", _controller.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_WithSortOrder_SetsCorrectViewBagValues()
    {
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        Assert.Equal("", _controller.ViewBag.NameSortParm);
        Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
    }

    // ===== Details Tests =====

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        var student = CreateTestStudent();

        var result = _controller.Details(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
        Assert.Equal("John", model.FirstMidName);
        Assert.Equal("Doe", model.LastName);
    }

    // ===== Create GET Tests =====

    [Fact]
    public void Create_Get_ReturnsViewWithStudentWithTodayDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    // ===== Create POST Tests =====

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            FirstMidName = "Jane",
            LastName = "Smith",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Create(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Create_Post_ValidStudent_AddsToDatabase()
    {
        var student = new Student
        {
            FirstMidName = "Jane",
            LastName = "Smith",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        _controller.Create(student);

        Assert.Single(_context.Students);
        var saved = _context.Students.First();
        Assert.Equal("Jane", saved.FirstMidName);
        Assert.Equal("Smith", saved.LastName);
    }

    [Fact]
    public void Create_Post_MinValueDate_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Jane",
            LastName = "Smith",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            FirstMidName = "Jane",
            LastName = "",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(student, result.Model);
    }

    [Fact]
    public void Create_Post_DateBefore1753_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Jane",
            LastName = "Smith",
            EnrollmentDate = new DateTime(1000, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ErrorCount > 0);
    }

    // ===== Edit GET Tests =====

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        var student = CreateTestStudent();

        var result = _controller.Edit(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ===== Edit POST Tests =====

    [Fact]
    public void Edit_Post_ValidStudent_RedirectsToIndex()
    {
        var student = CreateTestStudent();
        // Detach so EF doesn't track two instances
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var updatedStudent = new Student
        {
            ID = student.ID,
            FirstMidName = "Updated",
            LastName = "Name",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Edit(updatedStudent) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_MinValueDate_AddsModelError()
    {
        var student = CreateTestStudent();
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var updatedStudent = new Student
        {
            ID = student.ID,
            FirstMidName = "Updated",
            LastName = "Name",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Edit(updatedStudent) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsViewWithStudent()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Jane",
            LastName = "",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
    }

    // ===== Delete GET Tests =====

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        var student = CreateTestStudent();

        var result = _controller.Delete(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ===== DeleteConfirmed Tests =====

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        var student = CreateTestStudent();

        var result = _controller.DeleteConfirmed(student.ID) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Empty(_context.Students);
    }
}

