using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(), Mock.Of<ITempDataProvider>());
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department CreateTestDepartment(string name = "Engineering")
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000,
            StartDate = new DateTime(2020, 9, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course CreateTestCourse(int courseId = 1050, string title = "Chemistry", int credits = 3, int? departmentId = null)
    {
        if (departmentId == null)
        {
            var dept = CreateTestDepartment();
            departmentId = dept.DepartmentID;
        }
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = departmentId.Value
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    // ===== Index Tests =====

    [Fact]
    public void Index_ReturnsViewWithAllCourses()
    {
        var dept = CreateTestDepartment();
        CreateTestCourse(1050, "Chemistry", 3, dept.DepartmentID);
        CreateTestCourse(2021, "Composition", 3, dept.DepartmentID);

        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<IEnumerable<Course>>(result.Model);
        Assert.Equal(2, model.Count());
    }

    // ===== Details Tests =====

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        var course = CreateTestCourse();

        var result = _controller.Details(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
        Assert.Equal("Chemistry", model.Title);
    }

    // ===== Create GET Tests =====

    [Fact]
    public void Create_Get_ReturnsViewWithNewCourse()
    {
        CreateTestDepartment();

        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(0, model.CourseID);
    }

    // ===== Create POST Tests =====

    [Fact]
    public void Create_Post_ValidCourse_RedirectsToIndex()
    {
        var dept = CreateTestDepartment();
        var course = new Course
        {
            CourseID = 3001,
            Title = "Physics",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        var result = _controller.Create(course, null!) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Create_Post_ValidCourse_AddsToDatabase()
    {
        var dept = CreateTestDepartment();
        var course = new Course
        {
            CourseID = 3002,
            Title = "Biology",
            Credits = 4,
            DepartmentID = dept.DepartmentID
        };

        _controller.Create(course, null!);

        var saved = _context.Courses.Find(3002);
        Assert.NotNull(saved);
        Assert.Equal("Biology", saved.Title);
        Assert.Equal(4, saved.Credits);
