using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;

namespace ContosoUniversity.Tests;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new InstructorsController(_context);
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(), Mock.Of<ITempDataProvider>());
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Instructor CreateTestInstructor(string firstName = "John", string lastName = "Doe",
        DateTime? hireDate = null, bool withOffice = false)
    {
        var instructor = new Instructor
        {
            FirstMidName = firstName,
            LastName = lastName,
            HireDate = hireDate ?? new DateTime(2010, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        if (withOffice)
        {
            instructor.OfficeAssignment = new OfficeAssignment { Location = "Room 101" };
        }
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Course CreateTestCourse(int courseId, string title = "Test Course")
    {
        var dept = new Department
        {
            Name = "Test Dept",
            Budget = 50000,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    // ===== Index Tests =====

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructors()
    {
        CreateTestInstructor("Alice", "Alpha");
        CreateTestInstructor("Bob", "Beta");

        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<ContosoUniversity.Models.SchoolViewModels.InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_InstructorsOrderedByLastName()
    {
        CreateTestInstructor("Zoe", "Zulu");
        CreateTestInstructor("Alice", "Alpha");

        var result = _controller.Index(null, null) as ViewResult;

        var model = Assert.IsType<ContosoUniversity.Models.SchoolViewModels.InstructorIndexData>(result!.Model);
        var instructorList = model.Instructors.ToList();
        Assert.Equal("Alpha", instructorList[0].LastName);
        Assert.Equal("Zulu", instructorList[1].LastName);
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        var instructor = CreateTestInstructor();
        var course = CreateTestCourse(6001, "Test Course");
        var assignment = new CourseAssignment
        {
            InstructorID = instructor.ID,
            CourseID = course.CourseID
        };
        _context.CourseAssignments.Add(assignment);
        _context.SaveChanges();

        // Reload instructor with navigation properties
        var result = _controller.Index(instructor.ID, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<ContosoUniversity.Models.SchoolViewModels.InstructorIndexData>(result.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
    }

    // ===== Details Tests =====

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = CreateTestInstructor("Jane", "Smith");

        var result = _controller.Details(instructor.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Jane", model.FirstMidName);
        Assert.Equal("Smith", model.LastName);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Details(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ===== Create GET Tests =====

    [Fact]
    public void Create_Get_ReturnsViewWithInstructor()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(model.CourseAssignments);
        Assert.Empty(model.CourseAssignments);
    }

    // ===== Create POST Tests =====

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Jane",
            LastName = "Smith",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Create_Post_ValidInstructor_AddsToDatabase()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Jane",
            LastName = "Smith",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        _controller.Create(instructor, null!);

        Assert.Single(_context.Instructors);
        var saved = _context.Instructors.First();
        Assert.Equal("Jane", saved.FirstMidName);
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AssignsCourses()
    {
        var course = CreateTestCourse(7001, "Math");
        var instructor = new Instructor
        {
            FirstMidName = "Jane",
            LastName = "Smith",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, new[] { "7001" }) as RedirectToActionResult;

        Assert.NotNull(result);
        var saved = _context.Instructors.First();
        Assert.Single(saved.CourseAssignments);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            FirstMidName = "Jane",
            LastName = "",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!) as ViewResult;

        Assert.NotNull(result);
    }

    // ===== Edit GET Tests =====

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null as int?);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = CreateTestInstructor("Jane", "Smith");

        var result = _controller.Edit(instructor.ID as int?) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal(instructor.ID, model.ID);
    }

    // ===== Delete GET Tests =====

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = CreateTestInstructor();

        var result = _controller.Delete(instructor.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal(instructor.ID, model.ID);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ===== DeleteConfirmed Tests =====

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesInstructorAndRedirects()
    {
        var instructor = CreateTestInstructor(withOffice: true);

        var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Null(_context.Instructors.Find(instructor.ID));
    }

    [Fact]
    public void DeleteConfirmed_InstructorIsDeptAdmin_ClearsDepartmentAdmin()
    {
        var instructor = CreateTestInstructor();
        var dept = new Department
        {
            Name = "Test",
            Budget = 50000,
            StartDate = new DateTime(2020, 1, 1),
            InstructorID = instructor.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        _controller.DeleteConfirmed(instructor.ID);

        var updatedDept = _context.Departments.Find(dept.DepartmentID);
        Assert.NotNull(updatedDept);
        Assert.Null(updatedDept.InstructorID);
    }
}

