namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Constructor_SetsPageIndexAndTotalPages()
    {
        var items = new List<string> { "a", "b", "c" };

        var list = new PaginatedList<string>(items, 10, 2, 3);

        Assert.Equal(2, list.PageIndex);
        Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        Assert.Equal(3, list.Count);
    }

    [Fact]
    public void HasPreviousPage_True_WhenPageIndexGreaterThanOne()
    {
        var list = new PaginatedList<string>(new List<string>(), 10, 2, 5);

        Assert.True(list.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_False_WhenPageIndexIsOne()
    {
        var list = new PaginatedList<string>(new List<string>(), 10, 1, 5);

        Assert.False(list.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_True_WhenPageIndexLessThanTotalPages()
    {
        var list = new PaginatedList<string>(new List<string>(), 10, 1, 5);

        Assert.True(list.HasNextPage); // TotalPages = 2
    }

    [Fact]
    public void HasNextPage_False_WhenPageIndexEqualsTotalPages()
    {
        var list = new PaginatedList<string>(new List<string>(), 5, 1, 5);

        Assert.False(list.HasNextPage); // TotalPages = 1
    }

    [Fact]
    public void Create_ReturnsCorrectPage()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var result = PaginatedList<int>.Create(source, 2, 5);

        Assert.Equal(2, result.PageIndex);
        Assert.Equal(4, result.TotalPages);
        Assert.Equal(5, result.Count);
        Assert.Equal(6, result[0]);
        Assert.Equal(10, result[4]);
    }

    [Fact]
    public void Create_FirstPage_ContainsFirstItems()
    {
        var source = Enumerable.Range(1, 15).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 5);

        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(1, result[0]);
        Assert.Equal(5, result[4]);
    }

    [Fact]
    public void Create_LastPage_ContainsRemainingItems()
    {
        var source = Enumerable.Range(1, 12).AsQueryable();

        var result = PaginatedList<int>.Create(source, 3, 5);

        Assert.Equal(3, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(2, result.Count); // 12 items, page 3 of 5-per-page = 2 items
        Assert.Equal(11, result[0]);
        Assert.Equal(12, result[1]);
    }

    [Fact]
    public void Create_SinglePage_NoNextOrPrevious()
    {
        var source = Enumerable.Range(1, 3).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(1, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
        Assert.Equal(3, result.Count);
    }

    [Fact]
    public void TotalPages_CalculatedCorrectly()
    {
        // 7 items, 3 per page = ceil(7/3) = 3 pages
        var list = new PaginatedList<int>(new List<int>(), 7, 1, 3);
        Assert.Equal(3, list.TotalPages);
    }

    [Fact]
    public void TotalPages_ExactDivision()
    {
        // 10 items, 5 per page = 2 pages
        var list = new PaginatedList<int>(new List<int>(), 10, 1, 5);
        Assert.Equal(2, list.TotalPages);
    }
}

