using ContosoUniversity.Data;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests;

public class DbInitializerTests : IDisposable
{
    private readonly SchoolContext _context;

    public DbInitializerTests()
    {
        _context = TestDbContextFactory.Create();
    }

    public void Dispose()
    {
        _context.Dispose();
    }

    [Fact]
    public void Initialize_SeedsStudents()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(8, _context.Students.Count());
    }

    [Fact]
    public void Initialize_SeedsInstructors()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(5, _context.Instructors.Count());
    }

    [Fact]
    public void Initialize_SeedsDepartments()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(4, _context.Departments.Count());
    }

    [Fact]
    public void Initialize_SeedsCourses()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(7, _context.Courses.Count());
    }

    [Fact]
    public void Initialize_SeedsEnrollments()
    {
        DbInitializer.Initialize(_context);

        Assert.True(_context.Enrollments.Count() > 0);
        Assert.Equal(11, _context.Enrollments.Count());
    }

    [Fact]
    public void Initialize_SeedsOfficeAssignments()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(3, _context.OfficeAssignments.Count());
    }

    [Fact]
    public void Initialize_SeedsCourseAssignments()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(8, _context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_CalledTwice_DoesNotDuplicateData()
    {
        DbInitializer.Initialize(_context);
        DbInitializer.Initialize(_context);

        Assert.Equal(8, _context.Students.Count());
        Assert.Equal(5, _context.Instructors.Count());
    }

    [Fact]
    public void Initialize_SeedsSpecificStudentNames()
    {
        DbInitializer.Initialize(_context);

        var studentNames = _context.Students.Select(s => s.LastName).ToList();
        Assert.Contains("Alexander", studentNames);
        Assert.Contains("Alonso", studentNames);
        Assert.Contains("Anand", studentNames);
        Assert.Contains("Barzdukas", studentNames);
    }

    [Fact]
    public void Initialize_SeedsSpecificDepartmentNames()
    {
        DbInitializer.Initialize(_context);

        var deptNames = _context.Departments.Select(d => d.Name).ToList();
        Assert.Contains("English", deptNames);
        Assert.Contains("Mathematics", deptNames);
        Assert.Contains("Engineering", deptNames);
        Assert.Contains("Economics", deptNames);
    }

    [Fact]
    public void Initialize_SeedsSpecificCourseNames()
    {
        DbInitializer.Initialize(_context);

        var courseNames = _context.Courses.Select(c => c.Title).ToList();
        Assert.Contains("Chemistry", courseNames);
        Assert.Contains("Calculus", courseNames);
        Assert.Contains("Literature", courseNames);
    }

    [Fact]
    public void Initialize_EnrollmentsHaveCorrectGrades()
    {
        DbInitializer.Initialize(_context);

        var alexanderChemistry = _context.Enrollments
            .Include(e => e.Student)
            .Include(e => e.Course)
            .Single(e => e.Student.LastName == "Alexander" && e.Course.Title == "Chemistry");
        Assert.Equal(Grade.A, alexanderChemistry.Grade);
    }
}

