using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;

namespace ContosoUniversity.Tests;

public class DepartmentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly DepartmentsController _controller;

    public DepartmentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new DepartmentsController(_context);
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(), Mock.Of<ITempDataProvider>());
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department CreateTestDepartment(string name = "Engineering", decimal budget = 100000m)
    {
        var dept = new Department
        {
            Name = name,
            Budget = budget,
            StartDate = new DateTime(2020, 9, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Instructor CreateTestInstructor(string firstName = "John", string lastName = "Doe")
    {
        var instructor = new Instructor
        {
            FirstMidName = firstName,
            LastName = lastName,
            HireDate = new DateTime(2010, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    // ===== Index Tests =====

    [Fact]
    public void Index_ReturnsViewWithAllDepartments()
    {
        CreateTestDepartment("Engineering");
        CreateTestDepartment("Mathematics");

        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<IEnumerable<Department>>(result.Model);
        Assert.Equal(2, model.Count());
    }

    // ===== Details Tests =====

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithDepartment()
    {
        var dept = CreateTestDepartment();

        var result = _controller.Details(dept.DepartmentID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Department>(result.Model);
        Assert.Equal("Engineering", model.Name);
        Assert.Equal(100000m, model.Budget);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Details(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ===== Create GET Tests =====

    [Fact]
    public void Create_Get_ReturnsView()
    {
        CreateTestInstructor();

        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
    }

    // ===== Create POST Tests =====

    [Fact]
    public void Create_Post_ValidDepartment_RedirectsToIndex()
    {
        var dept = new Department
        {
            Name = "Physics",
            Budget = 200000m,
            StartDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Create(dept) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Create_Post_ValidDepartment_AddsToDatabase()
    {
        var dept = new Department
        {
            Name = "Physics",
            Budget = 200000m,
            StartDate = new DateTime(2023, 9, 1)
        };

        _controller.Create(dept);

        Assert.Single(_context.Departments);
        var saved = _context.Departments.First();
        Assert.Equal("Physics", saved.Name);
        Assert.Equal(200000m, saved.Budget);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsViewWithDepartment()
    {
        CreateTestInstructor();
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department { Budget = 100000m, StartDate = new DateTime(2023, 9, 1) };

        var result = _controller.Create(dept) as ViewResult;

        Assert.NotNull(result);
    }

    // ===== Edit GET Tests =====

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithDepartment()
    {
        CreateTestInstructor();
        var dept = CreateTestDepartment();

        var result = _controller.Edit((int?)dept.DepartmentID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Department>(result.Model);
        Assert.Equal(dept.DepartmentID, model.DepartmentID);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit((int?)9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ===== Edit POST Tests =====

    [Fact]
    public void Edit_Post_ValidDepartment_RedirectsToIndex()
    {
        CreateTestInstructor();
        var dept = CreateTestDepartment();
        _context.Entry(dept).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var updated = new Department
        {
            DepartmentID = dept.DepartmentID,
            Name = "Updated",
            Budget = 150000m,
            StartDate = new DateTime(2023, 1, 1)
        };

        var result = _controller.Edit(updated as Department) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        CreateTestInstructor();
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department
        {
            DepartmentID = 1,
            Budget = 100000m,
            StartDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Edit(dept as Department) as ViewResult;

        Assert.NotNull(result);
    }

    // ===== Delete GET Tests =====

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithDepartment()
    {
        var dept = CreateTestDepartment();

        var result = _controller.Delete(dept.DepartmentID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Department>(result.Model);
        Assert.Equal(dept.DepartmentID, model.DepartmentID);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ===== DeleteConfirmed Tests =====

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesDepartmentAndRedirects()
    {
        var dept = CreateTestDepartment();

        var result = _controller.DeleteConfirmed(dept.DepartmentID) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Null(_context.Departments.Find(dept.DepartmentID));
    }
}

